{"version":3,"sources":["../../src/config/env.validation.ts"],"sourcesContent":["import * as Joi from 'joi';\n\nexport const envValidationSchema = Joi.object({\n  NODE_ENV: Joi.string()\n    .valid('development', 'production', 'test')\n    .default('development'),\n  PORT: Joi.number().port().default(4000),\n  DATABASE_URL: Joi.string().min(10).required(),\n  DIRECT_URL: Joi.string().min(10).required(),\n  SWAGGER_ENABLED: Joi.string().valid('true', 'false').optional(),\n  CORS_ORIGIN: Joi.string().optional().default('*'),\n\n  // Auth: JWT\n  JWT_ACCESS_SECRET: Joi.string().min(16).required(),\n  JWT_REFRESH_SECRET: Joi.string().min(16).required(),\n  JWT_ACCESS_EXPIRY: Joi.string().optional().default('15m'),\n  JWT_REFRESH_EXPIRY: Joi.string().optional().default('7d'),\n\n  // Auth: Google OAuth\n  GOOGLE_CLIENT_ID: Joi.string().min(1).required(),\n  GOOGLE_CLIENT_SECRET: Joi.string().min(1).required(),\n  GOOGLE_CALLBACK_URL: Joi.string().uri().required(),\n  FRONTEND_URL: Joi.string().uri().required(),\n});\n"],"names":["envValidationSchema","Joi","object","NODE_ENV","string","valid","default","PORT","number","port","DATABASE_URL","min","required","DIRECT_URL","SWAGGER_ENABLED","optional","CORS_ORIGIN","JWT_ACCESS_SECRET","JWT_REFRESH_SECRET","JWT_ACCESS_EXPIRY","JWT_REFRESH_EXPIRY","GOOGLE_CLIENT_ID","GOOGLE_CLIENT_SECRET","GOOGLE_CALLBACK_URL","uri","FRONTEND_URL"],"mappings":";;;;+BAEaA;;;eAAAA;;;6DAFQ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;AAEd,MAAMA,sBAAsBC,KAAIC,MAAM,CAAC;IAC5CC,UAAUF,KAAIG,MAAM,GACjBC,KAAK,CAAC,eAAe,cAAc,QACnCC,OAAO,CAAC;IACXC,MAAMN,KAAIO,MAAM,GAAGC,IAAI,GAAGH,OAAO,CAAC;IAClCI,cAAcT,KAAIG,MAAM,GAAGO,GAAG,CAAC,IAAIC,QAAQ;IAC3CC,YAAYZ,KAAIG,MAAM,GAAGO,GAAG,CAAC,IAAIC,QAAQ;IACzCE,iBAAiBb,KAAIG,MAAM,GAAGC,KAAK,CAAC,QAAQ,SAASU,QAAQ;IAC7DC,aAAaf,KAAIG,MAAM,GAAGW,QAAQ,GAAGT,OAAO,CAAC;IAE7C,YAAY;IACZW,mBAAmBhB,KAAIG,MAAM,GAAGO,GAAG,CAAC,IAAIC,QAAQ;IAChDM,oBAAoBjB,KAAIG,MAAM,GAAGO,GAAG,CAAC,IAAIC,QAAQ;IACjDO,mBAAmBlB,KAAIG,MAAM,GAAGW,QAAQ,GAAGT,